import { Icon } from "@/registry/p1/internal/icons";
import "./header.css";

function safeHref(h: string): string {
  return /^(https?:\/\/|\/|#)/.test(h) ? h : "#";
}

export interface HeaderLink {
  label: string;
  href: string;
}
export interface HeaderProps {
  logo: string;
  links: HeaderLink[];
  navAlign: "left" | "center" | "right";
  showSearch: "off" | "on";
  ctaLabel: string;
  ctaStyle: "primary" | "yellow" | "purple" | "outline" | "none";
  tone: "white" | "light" | "dark";
  border: "on" | "off";
  sticky: "off" | "on";
}

export function HeaderRender({ logo, links, navAlign, showSearch, ctaLabel, ctaStyle, tone, border, sticky }: HeaderProps) {
  const list = links || [];

  const logoEl = <span className="p1-header__logo">{logo}</span>;

  const nav = (
    <nav className="p1-header__nav">
      {list.map((l, i) => (
        <a key={i} href={safeHref(l.href)} className="p1-header__link">
          {l.label}
        </a>
      ))}
    </nav>
  );

  const actions = (
    <div className="p1-header__actions">
      {showSearch === "on" && <Icon name="search" className="p1-header__search-icon" />}
      {ctaStyle !== "none" && ctaLabel && (
        <span className="p1-header__cta" data-cta={ctaStyle}>
          {ctaLabel}
        </span>
      )}
      <button type="button" aria-label="Menu" className="p1-header__burger">
        <Icon name="menu" className="p1-header__burger-icon" />
      </button>
    </div>
  );

  return (
    <header
      className="p1-header"
      data-tone={tone}
      data-border={border}
      data-sticky={sticky === "on" ? "on" : undefined}
    >
      <div className="p1-header__inner">
        {navAlign === "left" && (
          <>
            {logoEl}
            <span className="p1-header__gap-start">{nav}</span>
            <span className="p1-header__spacer" />
            {actions}
          </>
        )}
        {navAlign === "right" && (
          <>
            {logoEl}
            <span className="p1-header__spacer" />
            {nav}
            <span className="p1-header__gap-end">{actions}</span>
          </>
        )}
        {navAlign === "center" && (
          <>
            {logoEl}
            <span className="p1-header__spacer" />
            {nav}
            <span className="p1-header__spacer" />
            {actions}
          </>
        )}
      </div>
    </header>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { HeaderRender, type HeaderProps, type HeaderLink } from "./header";
export type { HeaderProps, HeaderLink };

export const HeaderBlock: ComponentConfig<HeaderProps> = {
  fields: {
    logo: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Brand name or wordmark shown in the header." },
    },
    links: {
      type: "array",
      arrayFields: {
        label: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Nav link label. 1–2 words." },
        },
        href: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { exclude: true },
        },
      },
      defaultItemProps: { label: "Link", href: "#" },
      getItemSummary: (item: HeaderLink) => item.label || "Link",
    },
    navAlign: {
      type: "select" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
        { label: "Right", value: "right" },
      ],
    },
    showSearch: {
      type: "radio" as const,
      options: [
        { label: "Off", value: "off" },
        { label: "On", value: "on" },
      ],
    },
    ctaLabel: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Header CTA label. 2–4 words." },
    },
    ctaStyle: {
      type: "select" as const,
      options: [
        { label: "Primary", value: "primary" },
        { label: "Yellow", value: "yellow" },
        { label: "Purple", value: "purple" },
        { label: "Outline", value: "outline" },
        { label: "None", value: "none" },
      ],
    },
    tone: {
      type: "select" as const,
      options: [
        { label: "White", value: "white" },
        { label: "Light", value: "light" },
        { label: "Dark", value: "dark" },
      ],
    },
    border: {
      type: "radio" as const,
      options: [
        { label: "On", value: "on" },
        { label: "Off", value: "off" },
      ],
    },
    sticky: {
      type: "radio" as const,
      options: [
        { label: "Off", value: "off" },
        { label: "On", value: "on" },
      ],
    },
  },
  defaultProps: {
    logo: "Pantheon",
    links: [
      { label: "Product", href: "#" },
      { label: "Solutions", href: "#" },
      { label: "Pricing", href: "#" },
      { label: "Docs", href: "#" },
      { label: "Customers", href: "#" },
    ],
    navAlign: "center",
    showSearch: "on",
    ctaLabel: "Start for free",
    ctaStyle: "primary",
    tone: "white",
    border: "on",
    sticky: "off",
  },
  render: HeaderRender,
};

export const meta = defineMeta({
  title: 'Header',
  description: 'Site navigation bar with logo, nav links, optional search, and a CTA button in white/light/dark tones; use as the page header/navbar.',
  categories: ["global"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-icons"],
});

.p1-header {
  padding-block: var(--p1-space-md);
  padding-inline: var(--p1-space-lg);
  position: relative;
}

.p1-header[data-sticky="on"] {
  position: sticky;
  top: 0;
  z-index: 20;
}

/* Tones */
.p1-header[data-tone="white"] { background-color: var(--p1-surface-default); }
.p1-header[data-tone="light"] { background-color: var(--p1-surface-subtle); }
.p1-header[data-tone="dark"] { background-color: var(--p1-surface-dark); }

/* Border */
.p1-header[data-border="on"] { border-block-end: 1px solid; }
.p1-header[data-tone="white"][data-border="on"],
.p1-header[data-tone="light"][data-border="on"] { border-color: var(--p1-border); }
.p1-header[data-tone="dark"][data-border="on"] { border-color: var(--p1-border-inverse); }

.p1-header__inner {
  align-items: center;
  display: flex;
  gap: 1.75rem;
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}

.p1-header__spacer { flex: 1; }

.p1-header__gap-start { margin-inline-start: 1.75rem; }
.p1-header__gap-end { margin-inline-start: 1.75rem; }

.p1-header__logo {
  font-size: var(--p1-text-xl);
  font-weight: 800;
  letter-spacing: -0.025em;
  white-space: nowrap;
}
.p1-header[data-tone="dark"] .p1-header__logo { color: var(--p1-fg-inverse); }
.p1-header[data-tone="white"] .p1-header__logo,
.p1-header[data-tone="light"] .p1-header__logo { color: var(--p1-fg-default); }

/* Nav */
.p1-header__nav {
  align-items: center;
  display: none;
  gap: 1.75rem;
}
@media (width >= 48rem) { .p1-header__nav { display: flex; } }

.p1-header__link {
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-medium);
  text-decoration: none;
  white-space: nowrap;
}
.p1-header[data-tone="dark"] .p1-header__link { color: var(--p1-fg-inverse-muted); }
.p1-header[data-tone="white"] .p1-header__link,
.p1-header[data-tone="light"] .p1-header__link { color: var(--p1-fg-muted); }

.p1-header__actions {
  align-items: center;
  display: flex;
  gap: var(--p1-space-md);
}

.p1-header__search-icon {
  block-size: 1.125rem;
  inline-size: 1.125rem;
}
.p1-header[data-tone="dark"] .p1-header__search-icon { color: var(--p1-fg-inverse-muted); }
.p1-header[data-tone="white"] .p1-header__search-icon,
.p1-header[data-tone="light"] .p1-header__search-icon { color: var(--p1-fg-muted); }

/* CTA button */
.p1-header__cta {
  border-radius: var(--p1-radius-pill);
  border: 1px solid;
  display: none;
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  padding: 0.625rem 1.25rem;
  white-space: nowrap;
}
@media (width >= 40rem) { .p1-header__cta { display: inline-flex; } }

.p1-header__cta[data-cta="primary"] {
  background-color: var(--p1-surface-dark);
  border-color: var(--p1-surface-dark);
  color: var(--p1-fg-inverse);
}
.p1-header__cta[data-cta="yellow"] {
  background-color: var(--p1-warning);
  border-color: var(--p1-warning);
  color: var(--p1-fg-default);
}
.p1-header__cta[data-cta="purple"] {
  background-color: var(--p1-accent);
  border-color: var(--p1-accent);
  color: var(--p1-fg-inverse);
}
.p1-header__cta[data-cta="outline"] {
  background-color: transparent;
}
.p1-header[data-tone="dark"] .p1-header__cta[data-cta="outline"] {
  border-color: var(--p1-border-inverse-strong);
  color: var(--p1-fg-inverse);
}
.p1-header[data-tone="white"] .p1-header__cta[data-cta="outline"],
.p1-header[data-tone="light"] .p1-header__cta[data-cta="outline"] {
  border-color: var(--p1-border-strong);
  color: var(--p1-fg-default);
}

/* Burger */
.p1-header__burger { background: none; border: none; cursor: pointer; padding: 0; }
.p1-header__burger-icon { block-size: 1.5rem; inline-size: 1.5rem; }
.p1-header[data-tone="dark"] .p1-header__burger { color: var(--p1-fg-inverse); }
.p1-header[data-tone="white"] .p1-header__burger,
.p1-header[data-tone="light"] .p1-header__burger { color: var(--p1-fg-default); }
@media (width >= 48rem) { .p1-header__burger { display: none; } }

